from typing import List

def remove_duplicates(numbers: List[int]) -> List[int]:
    count = {}
    for number in numbers:
        count[number] = count.get(number, 0) + 1
    return [number for number in numbers if count[number] == 1]

import math

def poly(xs: list, x: float):
    """
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
    """
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])

def find_zero(xs: list):
    """ xs are coefficients of a polynomial.
    find_zero find x such that poly(x) = 0.
    find_zero returns only only zero point, even if there are many.
    Moreover, find_zero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> round(find_zero([1, 2]), 2) # f(x) = 1 + 2x
    -0.5
    >>> round(find_zero([-6, 11, -6, 1]), 2) # (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
    """
    # Using the bisection method to find the root
    def bisection_method(f, a, b, tol=1e-7):
        while (b - a) / 2.0 > tol:
            midpoint = (a + b) / 2.0
            if f(midpoint) == 0:
                return midpoint
            elif f(a) * f(midpoint) < 0:
                b = midpoint
            else:
                a = midpoint
        return (a + b) / 2.0

    # Define the polynomial function based on the coefficients
    def polynomial_func(x):
        return poly(xs, x)

    # Initial range for the root-finding
    a, b = -1000, 1000  # Assuming the root is within this range
    return bisection_method(polynomial_func, a, b)

def fizz_buzz(n: int):
    """Return the number of times the digit 7 appears in integers less than n which are divisible by 11 or 13."""
    count = 0
    for i in range(n):
        if i % 11 == 0 or i % 13 == 0:
            count += str(i).count('7')
    return count

def largest_prime_factor(n: int):
    prime_factor = 1
    # Check for number of 2s that divide n
    while n % 2 == 0:
        prime_factor = 2
        n //= 2
    # n must be odd at this point, thus a skip of 2 (i.e., 3, 5, 7, ...) is used
    for i in range(3, int(n**0.5) + 1, 2):
        while n % i == 0:
            prime_factor = i
            n //= i
    # This condition is to check if n is a prime number greater than 2
    if n > 2:
        prime_factor = n
    return prime_factor

def correct_bracketing(brackets: str):
    balance = 0
    for char in brackets:
        if char == '(':  
            balance += 1
        elif char == ')':
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

