def anti_shuffle(s):
    words = s.split(' ')
    ordered_words = []
    for word in words:
        letters = sorted([c for c in word if c.isalpha()])
        non_letters = [c for c in word if not c.isalpha()]
        sorted_word = ''.join(letters) + ''.join(non_letters)
        ordered_words.append(sorted_word)
    return ' '.join(ordered_words)

def next_smallest(lst):
    unique_elements = set(lst)
    if len(unique_elements) < 2:
        return None
    sorted_elements = sorted(unique_elements)
    return sorted_elements[1]

def max_fill(grid, capacity):
    total_water = sum(sum(row) for row in grid)
    return (total_water // capacity) + (1 if total_water % capacity > 0 else 0)

def minPath(grid, k):
    from collections import deque

    N = len(grid)

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    min_path = None

    def bfs(start_x, start_y):
        nonlocal min_path
        queue = deque([(start_x, start_y, [grid[start_x][start_y]])])
        while queue:
            x, y, path = queue.popleft()
            if len(path) == k:
                if min_path is None or path < min_path:
                    min_path = path
                continue
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < N and 0 <= ny < N:
                    queue.append((nx, ny, path + [grid[nx][ny]]))

    for i in range(N):
        for j in range(N):
            bfs(i, j)

    return min_path

def is_equal_to_sum_even(n):
    """Evaluate whether the given number n can be written as the sum of exactly 4 positive even numbers"""
    return n >= 8 and n % 2 == 0

def sum_squares(lst):
    total = 0
    for i, value in enumerate(lst):
        if i % 3 == 0:
            total += value ** 2
        elif i % 4 == 0:
            total += value ** 3
    return total

def order_by_points(nums):
    def digit_sum(n):
        return sum(int(d) for d in str(abs(n)))
    return sorted(nums, key=lambda x: digit_sum(x)) if nums else []

def is_prime(num):
    if num <= 1:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def x_or_y(n, x, y):
    return x if is_prime(n) else y

def even_odd_count(num):
    even_count = 0
    odd_count = 0
    for digit in str(abs(num)):
        if int(digit) % 2 == 0:
            even_count += 1
        else:
            odd_count += 1
    return (even_count, odd_count)

import hashlib

def string_to_md5(text):
    if text == '':
        return None
    return hashlib.md5(text.encode()).hexdigest()
